-- DELETE — বেছে নিয়ে মোছা, ফেরানো যায়
START TRANSACTION;
DELETE FROM Employee WHERE DeptID = 'D02';
ROLLBACK;                    -- row গুলো ফিরে এল

-- TRUNCATE — সব যাবে, WHERE বসানোই যায় না
TRUNCATE TABLE Employee;
-- TRUNCATE TABLE Employee WHERE ...;   ← syntax error

-- DROP — টেবিলটাই নেই
DROP TABLE Employee;
SELECT * FROM Employee;      -- ERROR 1146: Table doesn't exist


-- referential integrity
CREATE TABLE Department (
    DeptID   VARCHAR(10) PRIMARY KEY,
    DeptName VARCHAR(50)
);

CREATE TABLE Employee (
    EmpID   INT PRIMARY KEY,
    EmpName VARCHAR(100),
    DeptID  VARCHAR(10),
    FOREIGN KEY (DeptID) REFERENCES Department(DeptID)
);

-- অস্তিত্বহীন department-এ কর্মী ঢোকানো যাবে না
INSERT INTO Employee VALUES (1, 'Rahim', 'D99');
-- ERROR 1452: a foreign key constraint fails

-- কর্মী থাকা অবস্থায় department মোছা যাবে না
DELETE FROM Department WHERE DeptID = 'D01';
-- ERROR 1451: a foreign key constraint fails

-- Employee রেফারেন্স করে, তাই Department TRUNCATE-ও করা যাবে না
TRUNCATE TABLE Department;
-- ERROR 1701: Cannot truncate a table referenced in a foreign key constraint

CREATE TABLE Student (
    StudentID   VARCHAR(10) PRIMARY KEY,
    StudentName VARCHAR(100) NOT NULL
);

CREATE TABLE Book (
    BookID    VARCHAR(10) PRIMARY KEY,
    BookTitle VARCHAR(200) NOT NULL
);

CREATE TABLE Borrow (
    StudentID  VARCHAR(10),
    BookID     VARCHAR(10),
    ReturnDate DATE,
    PRIMARY KEY (StudentID, BookID),
    FOREIGN KEY (StudentID) REFERENCES Student(StudentID),
    FOREIGN KEY (BookID)    REFERENCES Book(BookID)
);
